#include <vector>
#include <new>
#include <iostream>

template <class T>
struct CountingAlloc {
    using value_type = T;
    CountingAlloc() = default;
    template <class U>
    CountingAlloc(const CountingAlloc<U>&) noexcept {}
    T* allocate(std::size_t n) {
        ++allocations;
        return static_cast<T*>(::operator new(n * sizeof(T)));
    }
    void deallocate(T* p, std::size_t) noexcept { ::operator delete(p); }
    bool operator==(const CountingAlloc&) const noexcept { return true; }
    bool operator!=(const CountingAlloc&) const noexcept { return false; }
    static inline int allocations = 0;   // C++17 inline variable
};

int main() {
    std::vector<int, CountingAlloc<int>> v;
    v.reserve(1000);
    for (int i = 0; i < 1000; ++i) v.push_back(i);
    std::cout << CountingAlloc<int>::allocations << "\n";   // exactly 1
}

